#!/usr/bin/env node
"use strict";

// Checks the approved AnxHost CC logo and icon set in docs/anxhost/brand/
// (generated by scripts/anxhost-brand-build.js):
//   B1 every expected SVG and PNG exists, and each SVG is a complete document
//   B2 every PNG has the pixel size its file name states
//   B3 the .ico holds 16, 20, 24, 32, 48, 64 and 256 px PNG images
//   B4 icon-size images (app icon, tray, favicon) keep a visible silhouette on
//      both a dark (#202020) and a light (#f3f3f3) Windows taskbar: at most 5%
//      of their opaque edge pixels may fall below 3:1 contrast (WCAG non-text).
//      Before the rim was added, 95-100% did on the dark taskbar.
//
// Uses only Node built-ins (a minimal PNG decoder for 8-bit RGB/RGBA).
// Usage: node scripts/anxhost-brand-assets-smoke.js

const fs = require("fs");
const path = require("path");
const zlib = require("zlib");

const root = path.resolve(__dirname, "..");
const BRAND = path.join(root, "docs", "anxhost", "brand");

const SVGS = [
  "anxhost-icon-small.svg",
  "anxhost-mark-option-a-dark.svg", "anxhost-mark-option-a-light.svg", "anxhost-mark-option-b.svg",
  "anxhost-lockup-option-a-dark.svg", "anxhost-lockup-option-a-light.svg",
  "anxhost-lockup-option-b-dark.svg", "anxhost-lockup-option-b-light.svg",
  "anxhost-wordmark-dark.svg", "anxhost-wordmark-light.svg",
  "anxhost-wordmark-tagline-dark.svg", "anxhost-wordmark-tagline-light.svg",
];
const ICON_SIZES = [16, 20, 24, 32, 48, 64, 128, 256, 512, 1024];
const PNGS = [
  ...ICON_SIZES.map((s) => [`png/app-icon/anxhost-app-icon-${s}.png`, s]),
  ...[16, 20, 24, 32].map((s) => [`png/tray/anxhost-tray-${s}.png`, s]),
  ...[16, 32, 48].map((s) => [`png/favicon/anxhost-favicon-${s}.png`, s]),
  ...[180, 192, 512].map((s) => [`png/touch/anxhost-touch-${s}.png`, s]),
  ...["a-dark", "a-light", "b"].map((v) => [`png/marks/anxhost-mark-option-${v}-512.png`, 512]),
];
const ICO_SIZES = [16, 20, 24, 32, 48, 64, 256];
// Icon-size images whose silhouette must survive a taskbar of either theme.
const SILHOUETTE = [
  ...[16, 20, 24, 32, 48, 64, 128, 256].map((s) => `png/app-icon/anxhost-app-icon-${s}.png`),
  ...[16, 20, 24, 32].map((s) => `png/tray/anxhost-tray-${s}.png`),
  ...[16, 32, 48].map((s) => `png/favicon/anxhost-favicon-${s}.png`),
];
const TASKBARS = { dark: [32, 32, 32], light: [243, 243, 243] };
const MAX_LOW_EDGE_SHARE = 0.05;

// ---------------------------------------------------------------- PNG decoding
function decodePng(buffer) {
  if (buffer.readUInt32BE(0) !== 0x89504e47) throw new Error("not a PNG");
  let offset = 8;
  let header = null;
  const idat = [];
  while (offset < buffer.length) {
    const length = buffer.readUInt32BE(offset);
    const type = buffer.toString("ascii", offset + 4, offset + 8);
    const data = buffer.subarray(offset + 8, offset + 8 + length);
    if (type === "IHDR") {
      header = { width: data.readUInt32BE(0), height: data.readUInt32BE(4), depth: data[8], colorType: data[9], interlace: data[12] };
    } else if (type === "IDAT") {
      idat.push(data);
    } else if (type === "IEND") {
      break;
    }
    offset += 12 + length;
  }
  if (!header) throw new Error("PNG has no IHDR");
  const channels = { 2: 3, 6: 4 }[header.colorType];
  if (header.depth !== 8 || !channels || header.interlace !== 0) {
    throw new Error(`unsupported PNG (depth ${header.depth}, colour type ${header.colorType}, interlace ${header.interlace})`);
  }
  const raw = zlib.inflateSync(Buffer.concat(idat));
  const { width, height } = header;
  const stride = width * channels;
  const pixels = Buffer.alloc(width * height * 4);
  let previous = Buffer.alloc(stride);
  for (let y = 0; y < height; y += 1) {
    const filter = raw[y * (stride + 1)];
    const line = Buffer.from(raw.subarray(y * (stride + 1) + 1, (y + 1) * (stride + 1)));
    for (let i = 0; i < stride; i += 1) {
      const left = i >= channels ? line[i - channels] : 0;
      const up = previous[i];
      const upLeft = i >= channels ? previous[i - channels] : 0;
      let add = 0;
      if (filter === 1) add = left;
      else if (filter === 2) add = up;
      else if (filter === 3) add = (left + up) >> 1;
      else if (filter === 4) {
        const p = left + up - upLeft;
        const pa = Math.abs(p - left); const pb = Math.abs(p - up); const pc = Math.abs(p - upLeft);
        add = pa <= pb && pa <= pc ? left : pb <= pc ? up : upLeft;
      } else if (filter !== 0) throw new Error(`bad PNG filter ${filter}`);
      line[i] = (line[i] + add) & 0xff;
    }
    for (let x = 0; x < width; x += 1) {
      const target = (y * width + x) * 4;
      pixels[target] = line[x * channels];
      pixels[target + 1] = line[x * channels + 1];
      pixels[target + 2] = line[x * channels + 2];
      pixels[target + 3] = channels === 4 ? line[x * channels + 3] : 255;
    }
    previous = line;
  }
  return { width, height, pixels };
}

// ---------------------------------------------------------------- contrast
const channel = (c) => { const v = c / 255; return v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4; };
const luminance = ([r, g, b]) => 0.2126 * channel(r) + 0.7152 * channel(g) + 0.0722 * channel(b);
const contrast = (a, b) => { const x = luminance(a); const y = luminance(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); };

// Share of opaque edge pixels (opaque, with a transparent 4-neighbour) that
// fall below 3:1 against the background once composited over it.
function lowEdgeShare({ width, height, pixels }, background) {
  const opaque = (x, y) => x >= 0 && y >= 0 && x < width && y < height && pixels[(y * width + x) * 4 + 3] > 200;
  let edges = 0;
  let low = 0;
  for (let y = 0; y < height; y += 1) {
    for (let x = 0; x < width; x += 1) {
      if (!opaque(x, y)) continue;
      if (opaque(x - 1, y) && opaque(x + 1, y) && opaque(x, y - 1) && opaque(x, y + 1)) continue;
      const i = (y * width + x) * 4;
      const alpha = pixels[i + 3] / 255;
      const colour = [0, 1, 2].map((k) => pixels[i + k] * alpha + background[k] * (1 - alpha));
      edges += 1;
      if (contrast(colour, background) < 3) low += 1;
    }
  }
  return edges ? low / edges : 1;
}

// ---------------------------------------------------------------- checks
const failures = [];
const check = (id, ok, message) => {
  console.log(`${ok ? "PASS" : "FAIL"} ${id} ${message}`);
  if (!ok) failures.push(id);
};

function run() {
  // B1
  for (const name of SVGS) {
    const file = path.join(BRAND, "svg", name);
    const text = fs.existsSync(file) ? fs.readFileSync(file, "utf8") : "";
    const complete = /^<svg [^>]*viewBox="[\d. ]+"/.test(text) && text.trimEnd().endsWith("</svg>") && !/NaN|undefined/.test(text);
    check("B1", complete, `svg/${name} ${text ? (complete ? "complete" : "malformed") : "missing"}`);
  }
  // B2
  const decoded = new Map();
  for (const [rel, size] of PNGS) {
    const file = path.join(BRAND, rel);
    if (!fs.existsSync(file)) { check("B2", false, `${rel} missing`); continue; }
    const image = decodePng(fs.readFileSync(file));
    decoded.set(rel, image);
    check("B2", image.width === size && image.height === size, `${rel} ${image.width}x${image.height} (expected ${size})`);
  }
  // B3
  const icoFile = path.join(BRAND, "png", "app-icon", "anxhost-app-icon.ico");
  if (!fs.existsSync(icoFile)) {
    check("B3", false, "anxhost-app-icon.ico missing");
  } else {
    const ico = fs.readFileSync(icoFile);
    const count = ico.readUInt16LE(4);
    const sizes = [];
    for (let i = 0; i < count; i += 1) {
      const entry = 6 + i * 16;
      const length = ico.readUInt32LE(entry + 8);
      const offset = ico.readUInt32LE(entry + 12);
      const image = decodePng(ico.subarray(offset, offset + length));
      const declared = ico[entry] || 256;
      sizes.push(image.width === declared && image.height === declared ? declared : `${declared}!=${image.width}`);
    }
    check("B3", ico.readUInt16LE(2) === 1 && sizes.join(",") === ICO_SIZES.join(","), `ico sizes ${sizes.join(", ")}`);
  }
  // B4
  for (const rel of SILHOUETTE) {
    const image = decoded.get(rel);
    if (!image) continue;
    for (const [theme, background] of Object.entries(TASKBARS)) {
      const share = lowEdgeShare(image, background);
      check("B4", share <= MAX_LOW_EDGE_SHARE, `${rel} on ${theme} taskbar: ${(share * 100).toFixed(1)}% of edge below 3:1 (max ${MAX_LOW_EDGE_SHARE * 100}%)`);
    }
  }
}

try {
  run();
} catch (error) {
  console.error(error?.stack || error);
  failures.push("error");
}
if (failures.length) {
  console.error(`ANXHOST BRAND ASSETS SMOKE: FAIL (${failures.length})`);
  process.exitCode = 1;
} else {
  console.log("ANXHOST BRAND ASSETS SMOKE: PASS");
}
